-rc.3\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-native-command\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-sandbox\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session-persistence\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session-projection\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session-projection-cache\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session-query\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session-title\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-skill\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-storage\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-storage-domain\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-subagent\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-timeout\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-tool-todo\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-typert-registry\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-util-code-language\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-util-crypto\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-util-time\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-util-values\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-util-workspace-path\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-workspace\": \"0.2.1-rc.3\",\n    \"@floating-ui/react\": \"^0.27.20\",\n    \"@shikijs/langs\": \"4.5.0\",\n    \"@testing-library/dom\": \"^10.4.1\",\n    \"@testing-library/react\": \"^16.0.0\",\n    \"@types/katex\": \"0.16.8\",\n    \"@types/node\": \"^22.19.0\",\n    \"@types/react\": \"^18.0.0\",\n    \"@types/react-dom\": \"^18.0.0\",\n    \"@types/three\": \"^0.185.4\",\n    \"anser\": \"2.3.5\",\n    \"clsx\": \"2.1.1\",\n    \"diff\": \"9.0.0\",\n    \"echarts\": \"^5.6.0\",\n    \"echarts-wordcloud\": \"2.1.0\",\n    \"immer\": \"11.1.21\",\n    \"jsdom\": \"^25.0.0\",\n    \"lightningcss\": \"^1.25.0\",\n    \"maplibre-gl\": \"6.16.0\",\n    \"mdast-util-gfm\": \"3.1.0\",\n    \"mdast-util-math\": \"3.0.0\",\n    \"mermaid\": \"11.16.0\",\n    \"micromark-extension-gfm\": \"3.0.0\",\n    \"micromark-extension-math\": \"3.1.0\",\n    \"react-dom\": \"^18.3.1\",\n    \"semver\": \"^7.8.5\",\n    \"shiki\": \"4.5.0\",\n    \"simple-icons\": \"16.35.0\",\n    \"three\": \"^0.180.0\",\n    \"tsdown\": \"^0.22.2\",\n    \"tsx\": \"^4.0.0\",\n    \"typescript\": \"^5.6.0\",\n    \"vite\": \"^6.0.0\",\n    \"vitest\": \"^3.0.0\",\n    \"yaml\": \"^2.4.2\",\n    \"zustand\": \"5.0.15\"\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/clean.mjs && tsc -p tsconfig.json && tsdown\",\n    \"test\": \"vitest run\",\n    \"check\": \"node scripts/clean.mjs && tsc -p tsconfig.json && vitest run && tsdown && node scripts/check-standalone.mjs && node scripts/check-map-assets.mjs\",\n    \"check:host-api\": \"node scripts/check-host-api.mjs\",\n    \"prepack\": \"node scripts/prepack.mjs\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [],\n      \"platform\": \"web\"\n    }\n  },\n  \"packageManager\": \"pnpm@11.7.0\",\n  \"engines\": {\n    \"dsh\": \"^0.2.0-rc.1 || ^0.2.1-rc.1 || ^0.2.2-alpha.2\",\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"pnpm\": \">=11.7.0 <12\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-api-session-controller\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-store\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-chat\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-conversation\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-renderer\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-session\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-tool\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-session\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-skill\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-system-prompt\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-util-values\": {\n      \"optional\": true\n    }\n  },\n  \"dshGo\": {\n    \"v\": 1,\n    \"title\": {\n      \"zh\": \"GenUI\",\n      \"en\": \"GenUI\"\n    },\n    \"icon\": \"chart\",\n    \"contributes\": {\n      \"composer.actions\": [\n        {\n          \"id\": \"open-genui\",\n          \"label\": {\n            \"zh\": \"GenUI\",\n            \"en\": \"GenUI\"\n          },\n          \"icon\": \"chart\",\n          \"effect\": {\n            \"type\": \"open\",\n            \"page\": \"panel:genui\"\n          }\n        }\n      ],\n      \"panels\": [\n        {\n          \"id\": \"genui\",\n          \"title\": {\n            \"zh\": \"GenUI\",\n            \"en\": \"GenUI\"\n          },\n          \"icon\": \"chart\",\n          \"placement\": [\n            \"session.tab\",\n            \"chat.panel\"\n          ]\n        }\n      ]\n    }\n  }\n}\n"
