      "path": "src/plugin/tool.ts",
      "content": "/**\n * The `render_ui` tool: a model-facing channel that renders a GenUI spec as\n * an interactive card in the conversation TOOL ROW (route A of the design\n * doc). The ```dsh-ui fence channel renders inline in the reply; this tool\n * renders in the tool row and rides the harness's result `meta` projection:\n * `presentationMeta` stores the repaired spec, the browser toolview\n * (`src/client/toolview.tsx`) reads it from the result node and renders.\n *\n * Zero runtime harness imports, deliberately: an external plugin's node half\n * must not depend on the harness module graph at runtime (the profile\n * resolves only the plugin package itself). The definition is therefore a\n * plain `ToolDefinition` object — the exact shape `defineTool` returns — with\n * the arguments schema authored as JSON Schema (the harness validates args\n * and output with the same JSON Schema validator defineTool uses). Deep\n * validation, deterministic repair, and resource limits live in the shared\n * guard (`src/client/guard.ts`), which the schema deliberately stays loose\n * enough to reach.\n * @module @changfenhuang/dsh-genui/plugin/tool\n */\n\nimport type { ContentBlock } from '@deepseek-ai/dsh-llm'\nimport type { JsonValue } from '@deepseek-ai/dsh-util-values'\nimport type { GenericCallView, GenericResultView, JsonSchemaNode, ToolDefinition } from '@deepseek-ai/dsh-tools'\nimport {\n  isRenderableProcess, processGenuiSpec,\n} from '../client/guard.ts'\nimport type { GenuiProcessResult } from '../client/guard.ts'\nimport { completeFenceJson } from '../shared/fence-repair.ts'\nimport { droppedNodeFailure } from './genui-diagnostic.ts'\nimport { collectInlineContentWarnings } from './inline-content-diagnostic.ts'\nimport type { GenuiSpec } from '../client/spec.ts'\nimport { toDshGoView } from './dsh-go-view.ts'\nimport { dualNativeFence } from './dsh-go-compiler.ts'\n\n/**\n * Arguments schema: an open `spec` slot. The schema must NOT reject anything\n * the guard could repair — the model's component trees are imperfect by\n * nature, and the guard heals them; argument validation would only strand\n * them. `additionalProperties: false` keeps the call shape honest.\n *\n * `spec` IS typed `object` on purpose: the guard can only repair plain\n * records (a serialized JSON string, array, or scalar root is unusable), so\n * argument validation rejecting non-objects loses nothing repairable — and\n * it stops the model from double-encoding the tree as a string (observed\n * twice in the wild), failing fast with a clear schema error instead.\n */\nconst RENDER_UI_PARAMETERS: Record<string, unknown> = {\n  type: 'object',\n  properties: {\n    spec: {\n      type: 'object',\n      description: [\n      'Render structured UI for the user (tool-row card). USE THIS whenever the answer contains ≥3 parallel points, a comparison, numbers/metrics, a step sequence, a flow, or a status/report — do NOT write those as markdown bullets or a markdown table.',\n      'Same white-listed vocabulary as the ```dsh-ui fence (see the GenUI system-prompt section). Pick the fence when the UI belongs in the message body; pick this tool when the deliverable is a self-contained card.',\n      'Deep-validated and repaired by the renderer. Pass the spec as a JSON OBJECT — never as a serialized JSON string (a string fails argument validation).',\n    ].join(' '),\n      // Structural hints for the tool-call bridge. A bare `object` here was\n      // observed to make some bridge layers stringify the whole spec into an\n      // OpenAI-style `{ arguments: \"<JSON>\" }` wrapper (and to corrupt long\n      // specs mid-stream). Declaring the known top-level fields gives the\n      // bridge a concrete shape to serialize directly, while the schema stays\n      // deliberately open (unknown keys tolerated, `items` elements are free\n      // objects) so the guard — not the schema — remains the repair authority.\n      properties: {\n        title: { type: 'string', description: 'Short title shown as the card banner.' },\n        gap: { type: 'number', description: 'Vertical gap between root items in px.' },\n        panel: { type: 'boolean', description: 'Panel-only: renders into the session panel dock instead of the message flow.' },\n        items: {\n          type: 'array',\n          description: 'Root component list (white-listed vocabulary).',\n          items: { type: 'object' },\n        },\n      },\n    },\n  },\n  required: ['spec'],\n  additionalProperties: false,\n}\n\n/** The tool's canonical value is a short model-facing summary string. */\nconst RENDER_UI_OUTPUT_SCHEMA: JsonSchemaNode = { type: 'string', description: 'One-line human-readable render summary for the model.' }\n\n/**\n * Read the `spec` argument defensively (presenters run on replayed args).\n *\n * The harness tool-call bridge has been observed to deliver arguments in\n * shapes other than the authored `{ spec: <object> }`:\n * - `{ spec: \"<JSON string>\" }` — spec serialized to text;\n * - `{ arguments: \"<JSON string>\" }` / `{ arguments: <object> }` — a\n *   double-encoded wrapper from the SDK tool-call bridge (seen live in the\n *   web GUI: small specs arrived wrapped this way, large specs arrived with\n *   their JSON corrupted mid-stream);\n * - a bare JSON string (double-encoded root).\n * Each shape is unwrapped here so the guard can repair the actual tree.\n * Corrupted JSON cannot be recovered (bytes were lost in transit): it yields\n * `undefined` plus a diagnostic log line for the transport-layer bug.\n */\nfunction specOf(args: unknown): unknown {\n  if (typeof args === 'string') {\n    return parseSpecJson(args, 'bare-string')\n  }\n  if (typeof args !== 'object' || args === null) return undefined\n  const record = args as Record<string, unknown>\n  if ('spec' in record) {\n    const s = record.spec\n    if (typeof s === 'string') return parseSpecJson(s, 'spec-string')\n    return unwrapSpec(s, 'spec')\n  }\n  if ('arguments' in record) {\n    const a = record.arguments\n    if (typeof a === 'string') return parseSpecJson(a, 'arguments-string')\n    if (typeof a === 'object' && a !== null) return unwrapSpec(a, 'arguments')\n  }\n  return undefined\n}\n\n/**\n * Peel nested `{ spec: ... }` wrapper layers. Observed bridge shapes nest the\n * authored `spec` object one or more levels deep (e.g. the serialized text\n * inside `{ arguments: \"...\" }` is itself `{ spec: { title, gap, items } }`),\n * so unwrapping stops only at a value that carries no `spec` key.\n */\nfunction unwrapSpec(value: unknown, shape: string): unknown {\n  if (typeof value === 'object' && value !== null) {\n    const record = value as Record<string, unknown>\n    if ('spec' in record) {\n      const s = record.spec\n      if (typeof s === 'string') return parseSpecJson(s, `${shape}/spec-string`)\n      return unwrapSpec(s, `${shape}/spec`)\n    }\n  }\n  return value\n}\n\n/** Try to decode a serialized spec; log a diagnostic when it is broken. */\nfunction parseSpecJson(raw: string, shape: string): unknown {\n  try {\n    return unwrapSpec(JSON.parse(raw), shape)\n  } catch (error: unknown) {\n    const detail = error instanceof Error ? error.message : String(error)\n    const pos = /position (\\d+)/.exec(detail)?.[1] ?? '?'\n    console.error(`[genui-tool] spec wrapped as ${shape} but its JSON is broken (${raw.length} bytes, error at ${pos}); cannot recover — bytes lost in transit`)\n    return undefined\n  }\n}\n\n/** Process a raw tool value once for all render-time decisions. */\nfunction processRenderableValue(value: unknown): GenuiProcessResult {\n  return processGenuiSpec(value)\n}\n\n/** Wrap model-facing validation fields in the stable GenUI protocol envelope. */\nfunction validationProtocol(lines: string[]): string {\n  return ['[genui-validation]', ...lines, 'reply_language=conversation'].join('\\n')\n}\n\n/** Render process diagnostics as stable model-facing warning fields. */\nfunction formatProcessWarnings(processed: GenuiProcessResult): string[] {\n  return processed.warnings.map(warning => {\n    if (warning.kind === 'alias' && warning.canonical !== undefined) {\n      const separator = warning.path.lastIndexOf('.')\n      const canonicalPath = `${separator < 0 ? '' : warning.path.slice(0, separator + 1)}${warning.canonical}`\n      return warning.message.includes('ignored')\n        ? `warning=alias_ignored path=${warning.path} canonical=${canonicalPath}`\n        : `warning=alias_normalized path=${warning.path} canonical=${canonicalPath}`\n    }\n    if (warning.kind === 'unknown-field') {\n      return `warning=unknown_field path=${JSON.stringify(warning.path)} detail=${JSON.stringify(warning.message)}`\n    }\n    if (warning.kind === 'truncated') {\n      return `warning=policy_truncated path=${JSON.stringify(warning.path)} detail=${JSON.stringify(warning.message)}`\n    }\n    return `warning=process detail=${JSON.stringify(warning.message)}`\n  })\n}\n\n/** 将行内字段的块级 Markdown 诊断写入稳定的验证协议。 */\nfunction formatInlineContentWarnings(spec: GenuiSpec): string[] {\n  return collectInlineContentWarnings(spec).map(warning =>\n    `warning=block_markdown path=${warning.path} kind=${warning.kind} replacement=${warning.replacement}`)\n}\n\n/** Format chart-specific process errors while keeping other schema errors generic. */\nfunction formatProcessFailure(processed: GenuiProcessResult): string | undefined {\n  const chartErrors = processed.errors.filter(error => /(?:variant is unsupported|kind must be bars, line, or donut|requires data or series|(?:data|series) is required for|(?:\\.data|\\.series)(?:\\[\\d+\\])?(?:\\.(?:data|label|value|color))? must|series is only supported for bars)/.test(error))\n  return chartErrors.length === 0 ? undefined : validationProtocol([\n    'status=invalid',\n    'error=invalid_chart_fields',\n    ...chartErrors.map(error => `diagnostic=${JSON.stringify(error)}`),\n    'next=fix_and_revalidate',\n  ])\n}\n\n/** Tool-call title shared by the pending and completed presentations. */\nfunction cardTitle(args: unknown): string | undefined {\n  const processed = processRenderableValue(specOf(args))\n  if (!isRenderableProcess(processed) || processed.spec === null) return undefined\n  return `渲染 UI：${processed.spec.title ?? '未命名'}`\n}\n\n/**\n * Build the render_ui tool definition. Registered by the plugin node half;\n * `ctx.tools.register` consumes it exactly like a `defineTool` result.\n */\nexport function createRenderUiTool(): ToolDefinition {\n  return {\n    name: 'render_ui',\n    description:\n      'Render an interactive UI card in the conversation tool row by passing a GenUI spec (a white-listed component tree; the same vocabulary as the ```dsh-ui fence, see the system prompt). '\n      + 'Use it when the user asks for a structured panel, dashboard, or form that belongs in the tool row rather than inline in the reply. '\n      + 'The card is interactive client-side (tabs, buttons, inputs, switches); components carrying an \"action\" field send [genui-action] back to you when the user interacts, and you should re-render the updated UI.',\n    parameters: RENDER_UI_PARAMETERS,\n    output: {\n      schema: RENDER_UI_OUTPUT_SCHEMA,\n      render(_args: unknown, value: JsonValue): ContentBlock[] {\n        return [{ type: 'text', text: String(value) }]\n      },\n      presentationMeta(args: unknown): JsonValue {\n        // The browser toolview reads the repaired spec from result meta. The\n        // spec is JSON-safe by construction (only string/number/boolean/array\n        // fields after repair), so the widening cast is lossless.\n        const processed = processRenderableValue(specOf(args))\n        if (!isRenderableProcess(processed) || processed.spec === null) return null\n        const nativeView = toDshGoView(processed.spec)\n        // Keep the original root fields for existing web clients and replay.\n        // dsh-go reads only the namespaced, read-only native projection.\n        return (nativeView === null ? processed.spec : {\n          ...processed.spec, 'dsh-go/view': nativeView,\n        }) as unknown as JsonValue\n      },\n    },\n    async execute(args: unknown): Promise<JsonValue> {\n      const processed = processRenderableValue(specOf(args))\n      if (processed.spec === null) {\n        return ['[genui-render]', 'status=invalid', 'error=invalid_spec', 'required=items', 'next=fix_and_retry', 'reply_language=conversation'].join('\\n')\n      }\n      if (!isRenderableProcess(processed)) {\n        throw new Error('render_ui spec invalid: ' + processed.errors.join('; '))\n      }\n      const spec = processed.spec\n      const warnings = formatProcessWarnings(processed)\n      return [\n        '[genui-render]',\n        'status=rendered',\n        ...(spec.title === undefined ? [] : [`title=${JSON.stringify(spec.title)}`]),\n        `rendered=${processed.renderedCount}`,\n        'action_feedback=[genui-action]',\n        ...warnings,\n        'reply_language=conversation',\n      ].join('\\n')\n    },\n    presentCall(args: unknown): GenericCallView | undefined {\n      const title = cardTitle(args)\n      return title === undefined ? undefined : { card: 'generic', title, kind: 'other' }\n    },\n    presentResult(args: unknown): GenericResultView | undefined {\n      const title = cardTitle(args)\n      return title === undefined ? undefined : { card: 'generic', title }\n    },\n  }\n}\n\n/**\n * The `validate_dsh_ui` tool: a model-facing pre-flight check for the\n * ```dsh-ui fence channel. The model calls it with the JSON text it is about\n * to put inside a fence; it reports whether the body parses as a valid GenUI\n * spec, and when it does not, WHERE it breaks and WHAT is likely wrong\n * (bracket counts, common typo classes) so the model can fix and re-validate\n * before emitting — turning \"render a red banner after the fact\" into\n * \"verify before you send\". Purely local: no LLM, no network, no DOM.\n */\nconst VALIDATE_DESCRIPTION =\n  'Validate the JSON body of a ```dsh-ui fence BEFORE emitting it — use for non-trivial specs (≥3 nodes or containing a table); skip for trivial ones (≤2 nodes). '\n  + 'Pass the exact JSON text you are about to put inside the fence as the \"spec\" argument (a string). '\n  + 'Returns a [genui-validation] protocol block with status, diagnostics, next action, and reply_language=conversation. '\n  + 'When invalid JSON is repairable, repaired_json contains the fixed body; emit it only with next=emit_repaired_fence. '\n  + 'A warning=unknown_field requires fixing the indicated path and another validation call. '\n  + 'A warning=block_markdown requires the indicated replacement node and another validation call. '\n  + 'When native_fence_json is returned, emit that exact JSON: it keeps the web items and adds the existing dsh-go native projection. Native [dsh-ui reply] messages carry visible choices, not hidden action payloads.'\n\nconst VALIDATE_PARAMETERS: Record<string, unknown> = {\n  type: 'object',\n  properties: {\n    spec: {\n      oneOf: [\n        { type: 'string', description: 'The exact JSON text of the fence body.' },\n        { type: 'object', description: 'The spec object (serialized before validation).' },\n      ],\n      description: 'The dsh-ui fence body to validate: pass the JSON as a string for an exact check, or as the spec object.',\n    },\n  },\n  required: ['spec'],\n  additionalProperties: false,\n}\n\n/** Read the fence-body text from the call args (string preferred, object serialized). */\nfunction fenceTextOf(args: unknown): string | null {\n  if (typeof args === 'string') return args\n  if (typeof args !== 'object' || args === null) return null\n  const record = args as Record<string, unknown>\n  const s = 'spec' in record ? record.spec : 'arguments' in record ? record.arguments : undefined\n  if (typeof s === 'string') return s\n  if (typeof s === 'object' && s !== null) return JSON.stringify(s)\n  return null\n}\n\n/** Count structural brackets outside string literals. */\nfunction bracketCounts(raw: string): { '{': number; '}': number; '[': number; ']': number } {\n  const counts = { '{': 0, '}': 0, '[': 0, ']': 0 }\n  let inString = false\n  let escaped = false\n  for (let i = 0; i < raw.length; i++) {\n    const ch = raw[i]!\n    if (escaped) {\n      escaped = false\n      continue\n    }\n    if (inString) {\n      if (ch === '\\\\') escaped = true\n      else if (ch === '\"') inString = false\n      continue\n    }\n    if (ch === '\"') {\n      inString = true\n      continue\n    }\n    if (ch === '{') counts['{'] += 1\n    else if (ch === '}') counts['}'] += 1\n    else if (ch === '[') counts['['] += 1\n    else if (ch === ']') counts[']'] += 1\n  }\n  return counts\n}\n\n/** Return stable structural count fields for an invalid JSON body. */\nfunction bracketDiagnostic(raw: string): string[] {\n  const c = bracketCounts(raw)\n  const fields = [`braces_open=${c['{']}`, `braces_close=${c['}']}`, `brackets_open=${c['[']}`, `brackets_close=${c[']']}`]\n  if (c['{'] !== c['}']) {\n    const d = c['{'] - c['}']\n    fields.push(`brace_delta=${d}`, `brace_action=${d > 0 ? `add:${d}` : `remove:${-d}`}`)\n  }\n  if (c['['] !== c[']']) {\n    const d = c['['] - c[']']\n    fields.push(`bracket_delta=${d}`, `bracket_action=${d > 0 ? `add:${d}` : `remove:${-d}`}`)\n  }\n  return fields\n}\n\nconst COMMON_CAUSES = 'likely_causes=unbalanced_delimiters,unescaped_quote,trailing_comma,unterminated_string'\n\n/** Build the validate_dsh_ui tool definition (registered alongside render_ui). */\nexport function createValidateDshUiTool(): ToolDefinition {\n  return {\n    name: 'validate_dsh_ui',\n    description: VALIDATE_DESCRIPTION,\n    parameters: VALIDATE_PARAMETERS,\n    output: {\n      schema: { type: 'string', description: 'Validation verdict for the model.' },\n      render(_args: unknown, value: JsonValue): ContentBlock[] {\n        return [{ type: 'text', text: String(value) }]\n      },\n    },\n    async execute(args: unknown): Promise<JsonValue> {\n      const raw = fenceTextOf(args)\n      if (raw === null || raw.trim() === '') {\n        return validationProtocol(['status=invalid', 'error=missing_spec', 'next=provide_spec'])\n      }\n      let parsed: unknown\n      try {\n        parsed = JSON.parse(raw)\n      } catch (error: unknown) {\n        const detail = error instanceof Error ? error.message : String(error)\n        // Pre-emission, both repair tiers are safe (no streaming half exists\n        // in a validation call). When the repair succeeds, hand the model the\n        // FIXED JSON instead of asking it to re-author the fix — re-writing\n        // the whole fence by hand is where the next typo comes from.\n        const repaired = completeFenceJson(raw)\n        if (repaired !== null) {\n          const repairedValue = JSON.parse(repaired.text) as unknown\n          const processed = processRenderableValue(repairedValue)\n          const chartFailure = formatProcessFailure(processed)\n          if (chartFailure !== undefined) return chartFailure\n          if (processed.spec !== null && processed.errors.length === 0) {\n            const warnings = formatProcessWarnings(processed)\n            const inlineWarnings = formatInlineContentWarnings(processed.spec)\n            const requiresCorrection = inlineWarnings.length > 0 || processed.warnings.some(warning => warning.kind === 'unknown-field')\n            return `${validationProtocol([\n              'status=invalid',\n              'error=invalid_json',\n              `detail=${JSON.stringify(detail)}`,\n              ...bracketDiagnostic(raw),\n              ...warnings,\n              ...inlineWarnings,\n              'repair=applied',\n              `repair_count=${repaired.repairs}`,\n              requiresCorrection ? 'next=fix_and_revalidate' : 'next=emit_repaired_fence',\n            ])}\\nrepaired_json:\\n\\`\\`\\`\\n${repaired.text}\\n\\`\\`\\``\n          }\n        }\n        return validationProtocol([\n          'status=invalid',\n          'error=invalid_json',\n          `detail=${JSON.stringify(detail)}`,\n          ...bracketDiagnostic(raw),\n          'repair=failed',\n          COMMON_CAUSES,\n          'next=fix_and_revalidate',\n        ])\n      }\n      const processed = processRenderableValue(parsed)\n      const chartFailure = formatProcessFailure(processed)\n      if (chartFailure !== undefined) return chartFailure\n      if (processed.spec === null || processed.errors.length > 0) {\n        const dropped = droppedNodeFailure(processed, parsed)\n        return dropped === undefined\n          ? validationProtocol([\n            'status=invalid',\n            'error=invalid_spec',\n            ...(processed.errors.length === 0\n              ? ['required=items', 'node_types=whitelist']\n              : processed.errors.map(error => `diagnostic=${JSON.stringify(error)}`)),\n            'next=fix_and_revalidate',\n          ])\n          : validationProtocol(['status=invalid', ...dropped, 'next=fix_and_revalidate'])\n      }\n      const warnings = formatProcessWarnings(processed)\n      const inlineWarnings = formatInlineContentWarnings(processed.spec)\n      const requiresCorrection = inlineWarnings.length > 0 || processed.warnings.some(warning => warning.kind === 'unknown-field')\n      const verdict = validationProtocol([\n        'status=valid', `rendered=${processed.renderedCount}`, ...warnings, ...inlineWarnings,\n        requiresCorrection ? 'next=fix_and_revalidate' : 'next=emit_fence',\n      ])\n      const native = requiresCorrection ? null:dualNativeFence(processed.spec)\n      return native === null ? verdict:`${verdict}\\nnative_fence_json:\\n\\`\\`\\`\\n${JSON.stringify(native)}\\n\\`\\`\\``\n    },\n    presentCall(): GenericCallView | undefined {\n      return { card: 'generic', title: '验证 dsh-ui 围栏', kind: 'other' }\n    },\n    presentResult(): GenericResultView | undefined {\n      return { card: 'generic', title: '验证 dsh-ui 围栏' }\n    },\n  }\n}\n"
    },
    {
      "path": "src/client/index.tsx",
      "content": "/**\n * dsh-genui browser half: the ```dsh-ui fence renderer, the keyed toolview\n * for the `render_ui` tool, and the session panel dock.\n *\n * Fence rendering uses the stock DSH DOM. `dom-fence.ts` observes the\n * conversation DOM, identifies `dsh-ui` blocks and mounts the renderer in\n * plugin-owned React roots. The plugin-owned GenuiActionContext relays\n * `[genui-action]` through the scoped conversation send.\n *\n * The renderer parses the fence body with the partial parser: while the reply\n * streams, every FINISHED component appears the moment its JSON object\n * closes, so the UI assembles top-down before the fence (or reply) completes.\n * A body with no finished component yet falls back to a plain code block.\n * @module @changfenhuang/dsh-genui/client\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-api-session-controller/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type { SessionId } from '@deepseek-ai/dsh-session/types'\nimport type { IConversation } from '@deepseek-ai/dsh-client-ui-conversation/client'\nimport { createElement } from 'react'\nimport type { ToolCallViewProps } from '@deepseek-ai/dsh-client-ui-tool/client'\nimport { installDomFenceRenderer } from './dom-fence.tsx'\nimport { installSidechatAdapter, type SidechatSurfaceService } from './sidechat-surface.tsx'\nimport { createFileLinkAvailability, withFileLinkContext, type FileLinkCordisContext } from './file-link-context.tsx'\nimport { createPanelSlashSource } from './panel-command.ts'\nimport { GenuiPanel, type GenuiPanelInjected } from './panel.tsx'\nimport { GenuiToolView } from './toolview.tsx'\nimport { mountAchievementToasts } from './achievement-toast.tsx'\nimport { bridgeHostLocale, t } from './i18n/index.ts'\nimport type { InputTriggerServiceContract } from '@deepseek-ai/dsh-client-ui-input-trigger/client'\nimport { assetUrl } from './asset-loader.ts'\n\n/** Add low-priority prefetch links for the lazy engine assets (mermaid/three).\n * Browser-dependent: some engines ignore `<link rel=prefetch>`; harmless\n * either way — the on-demand loader still covers a cache miss. Exported for\n * tests. */\nexport function prefetchGenuiAssets(): void {\n  if (typeof document === 'undefined') return\n  for (const file of ['mermaid.js', 'three.js']) {\n    if (document.head.querySelector(`link[rel=\"prefetch\"][href=\"${assetUrl(file)}\"]`) !== null) continue\n    const link = document.createElement('link')\n    link.rel = 'prefetch'\n    link.as = 'script'\n    link.href = assetUrl(file)\n    document.head.appendChild(link)\n  }\n}\n\n/** Session panel action loop: same [genui-action] contract as inline fences,\n * routed through the scoped conversation send (queued user message). The\n * prompt asks the model to re-run render_ui so the panel updates in place. */\nfunction panelActionSend(ctx: Context, sessionId: SessionId): GenuiPanelInjected {\n  const scoped = ctx.sessions.scope(sessionId)\n  const conversation = scoped?.get('conversation') as IConversation | undefined\n  return {\n    sessionId,\n    sendGenuiAction: (action, payload) => {\n      if (conversation === undefined) return\n      const payloadText = Object.keys(payload).length === 0\n        ? ''\n        : t('action.payload', { json: JSON.stringify(payload) })\n      void conversation.send(t('action.panel', { action, payload: payloadText })).catch((err: unknown) => {\n        // A failed prompt (session gone, agent busy) drops the action; the\n        // panel stays interactive — the component is not disabled. Log the\n        // failure WITHOUT the action payload or any secret values (the\n        // message may contain field content).\n        console.warn(`[genui] 面板动作 \"${action}\" 发送失败（session ${sessionId}）：`, err instanceof Error ? err.message : String(err))\n      })\n    },\n    insertTemplate: (text) => {\n      // Same insert channel as dsh-memory's organizeMemory: the standard\n      // conversation.input.for(scope).setDraft — templates land in the\n      // composer draft, not a queued message, so the user can edit before\n      // sending.\n      const input = (conversation as unknown as {\n        input?: { for?(actx: unknown): { setDraft(text: string): void } | undefined }\n      } | undefined)?.input?.for?.(scoped)\n      input?.setDraft(text)\n    },\n  }\n}\n\n/** Relay a `/panel <指令>` instruction to the model: the scoped conversation\n * send with an explicit panel-only directive, so the model replaces the\n * default panel with content tailored to the request. */\nfunction sendPanelInstruction(ctx: Context, sessionId: SessionId, instruction: string): void {\n  const scoped = ctx.sessions.scope(sessionId)\n  const conversation = scoped?.get('conversation') as IConversation | undefined\n  if (conversation === undefined) return\n  void conversation.send(`用户执行了 /panel 并请求：${instruction}。请只输出一个 panel:true 的 dsh-ui 围栏来更新会话面板，内容按请求定制；回复文本至多一行 10 字以内的确认（如\"已更新\"），不要解释、不要普通围栏。`).catch((err: unknown) => {\n    // A failed prompt drops the instruction; the default panel stays\n    // visible. Log without the instruction text (may contain secrets).\n    console.warn(`[genui] /panel 指令发送失败（session ${sessionId}）：`, err instanceof Error ? err.message : String(err))\n  })\n}\n\n/**\n * Inline-fence action relay (DOM channel): the same message template the\n * host action message template, so inline actions reach the model consistently.\n */\nfunction sendInlineGenuiAction(ctx: Context, sessionId: SessionId, action: string, payload: Record<string, unknown>): void {\n  const scoped = ctx.sessions.scope(sessionId)\n  const conversation = scoped?.get('conversation') as IConversation | undefined\n  if (conversation === undefined) return\n  const payloadText = Object.keys(payload).length === 0\n    ? ''\n    : t('action.payload', { json: JSON.stringify(payload) })\n  void conversation.send(t('action.inline', { action, payload: payloadText })).catch(() => {\n    // A failed prompt (session gone, agent busy) drops the action;\n    // the UI stays interactive — the component is not disabled.\n  })\n}\n\n/** Cordis client entry: install the fence renderer on boot, the keyed\n * toolview for the render_ui tool, and the session panel dock; returning the\n * disposers lets cordis tear all registrations down on plugin unload. */\nexport function apply(ctx: Context): () => void {\n  // Provider 提交所属线程身份和专属操作路由；DOM renderer 继续忽略这些 surface。\n  ctx.inject(['genuiSidechat'], scope => {\n    scope.effect(() => installSidechatAdapter(scope.get('genuiSidechat') as Partial<SidechatSurfaceService> | undefined), 'genui: host sidechat surface')\n  })\n  // BetterSidebar 保留现有 service，并沿用通用 sidechat surface contract。\n  ctx.inject(['betterSidebar'], scope => {\n    scope.effect(() => installSidechatAdapter(scope.get('betterSidebar') as Partial<SidechatSurfaceService> | undefined), 'genui: sidechat surface')\n  })\n  // Language: follow the host's DSH language preference when the deployment\n  // ships the locale service, otherwise fall back to browser detection. Read\n  // OPTIONALLY (never declared in `inject`) so a host without the\n  // service still renders — a declared-but-absent service would park the\n  // fiber forever and kill all GenUI rendering.\n  const localeDispose = bridgeHostLocale(ctx)\n  const fileLinkAvailability = createFileLinkAvailability(ctx as unknown as FileLinkCordisContext)\n  console.info('[genui] client active; fence-channel=dom')\n  const disposers: Array<() => void> = [\n    localeDispose,\n    installDomFenceRenderer(ctx, (sessionId, action, payload) => sendInlineGenuiAction(ctx, sessionId, action, payload), fileLinkAvailability),\n  ]\n  // Idle prefetch of the lazy engine assets: the browser downloads them at\n  // LOW priority whenever the page is idle, so the first mermaid/3D node in\n  // a session usually hits a warm cache instead of paying the fetch on first\n  // use. Never blocks first paint; the loader still handles a miss.\n  prefetchGenuiAssets()\n  // Achievement toasts (0.9.5): a body-level stack independent of the panel.\n  disposers.push(mountAchievementToasts())\n  // Keyed toolview: the harness dispatches 'tool.call.toolview' by wire tool\n  // name; registering under 'render_ui' gives the tool's result card the\n  // GenUI renderer (reading the repaired spec from result meta). The toolview\n  // also publishes every settled spec to the session panel store.\n  disposers.push(ctx.slots.inject('tool.call.toolview', () => ctx.slots.register({\n    name: 'tool.call.toolview',\n    key: 'render_ui',\n  }, (props: ToolCallViewProps) => withFileLinkContext(\n    ctx as unknown as FileLinkCordisContext,\n    fileLinkAvailability,\n    props.sessionId,\n    false,\n    createElement(GenuiToolView, props),\n  ))))\n  // Session panel dock: a session-scoped, always-present seat above the\n  // composer (TodoDock posture). Renders the session's latest render_ui\n  // spec in place; absent spec = no panel.\n  disposers.push(ctx.slots.inject('conversation.input.dock', () => ctx.slots.register({\n    name: 'conversation.input.dock',\n    id: 'genui-panel',\n    order: 50,\n    inject: (sessionId: SessionId): GenuiPanelInjected => ({\n      ...panelActionSend(ctx, sessionId),\n      fileLinkContext: { ctx: ctx as unknown as FileLinkCordisContext, availability: fileLinkAvailability },\n    }),\n  }, GenuiPanel)))\n  // /panel slash command: a deterministic, client-side entry point that\n  // opens the panel dock (publishes the default spec + expand request),\n  // clears it (/panel clear), or relays an instruction to the model\n  // (/panel <指令>) so the panel gets tailored content.\n  //\n  // inputTriggers is subscribed via cordis OPTIONAL injection (ctx.inject),\n  // NOT a one-shot ctx.get() at apply time: the service is typically\n  // provided by a different bundle than slots/sessions, so it can arrive\n  // AFTER apply() runs — a one-shot lookup would silently disable /panel\n  // even on hosts that DO ship the service (service arrival order race).\n  // ctx.inject activates the callback only when the service arrives (any\n  // order) and disposes with the subscription fiber; hosts without the\n  // service simply never register /panel, and rendering is unaffected\n  // either way.\n  ctx.inject(['inputTriggers'], (scope) => {\n    const slash = scope.get('inputTriggers') as InputTriggerServiceContract | undefined\n    if (slash === undefined) return\n    scope.effect(() => slash.registerSource(\n      createPanelSlashSource((sessionId, instruction) => sendPanelInstruction(ctx, sessionId, instruction)),\n    ), 'genui: /panel')\n  })\n  return () => {\n    for (const dispose of disposers) dispose()\n  }\n}\n\nexport type { SidechatSurface, SidechatSurfaceService } from './sidechat-surface.tsx'\n\n// Browser services the client entry needs: the slots registry (toolview +\n// dock) and sessions (scoped conversation send behind actions). This\n// declaration is what the host's fiber inject waiting uses — without it\n// apply() runs before the services bind and the whole plugin tree fails the\n// boot sweep.\n//\n// inputTriggers (the /panel command source) is deliberately NOT declared:\n// cordis `inject` is a hard activation gate — a declared service that is\n// never provided (pristine DSH shells ship no inputTriggers provider) parks\n// the fiber in waiting forever and apply() never runs, silently killing all\n// GenUI rendering. Instead the apply() body subscribes via ctx.inject\n// (optional injection): hosts with the service get /panel registered in any\n// arrival order, hosts without it never register /panel — and the renderer\n// itself never depends on the service either way.\nexport const inject = ['slots', 'sessions']\n\n/** Trusted host configuration, separate from model-authored JSON. */\nexport { GenuiMapContext, setGenuiMapConfig } from './map-config.ts'\nexport type { GenuiMapConfig, GenuiMapStyle } from './map-config.ts'\n"
    },
    {
      "path": "src/client/genui-runtime/limits.ts",
      "content": "/** Resource limits shared by GenUI repair, validation, and rendering. */\nexport const GENUI_LIMITS = {\n  /** Maximum nesting depth of the component tree. */\n  maxDepth: 8,\n  /** Maximum total nodes across the whole spec. */\n  maxNodes: 200,\n  /** Maximum length of any plain string field. */\n  maxString: 2000,\n  /** Maximum length of a `code` body. */\n  maxCode: 12_000,\n  /** Copy preview only; clipboard text keeps the existing maxCode limit. */\n  maxCopyPreview: 2000,\n  maxCopyPreviewLines: 30,\n  /** Maximum length of a mermaid source. */\n  maxMermaid: 8000,\n  /** Maximum `grid` columns. */\n  maxGridCols: 12,\n  /** Maximum `tabs` count. */\n  maxTabs: 12,\n  /** Bounded gallery/slide counts; carousel children also consume maxNodes. */\n  maxCarouselItems: 24,\n  maxImageGroupItems: 24,\n  /** Maximum `accordion` items. */\n  maxAccordionItems: 24,\n  /** Maximum `list` items. */\n  maxListItems: 50,\n  /** Maximum `select`/`radio` options. */\n  maxOptions: 50,\n  /** Maximum `table` rows / columns. */\n  maxTableRows: 50,\n  maxTableCols: 12,\n  /** Maximum `chart` data points per series. */\n  maxChartPoints: 60,\n  /** Maximum `plot` series and per-series parameters. */\n  maxPlotSeries: 8,\n  maxPlotParams: 6,\n  /** Maximum computed fields evaluated for one GenUI specification. */\n  maxComputedFields: 50,\n  /** Maximum `scene3d` meshes. */\n  maxMeshes: 5,\n  maxMapLocations: 50,\n  maxMapRoutes: 8,\n  maxMapRoutePoints: 500,\n  /** Maximum editable text length and entity-card record counts. */\n  maxEditorChars: 12_000,\n  maxEntityMetadata: 24,\n  maxEntityActions: 8,\n  /** Maximum `quiz` options. */\n  maxQuizOptions: 8,\n  /** Maximum `steps` / `timeline` / `breadcrumb` / `keyvalue` entries. */\n  maxSteps: 24,\n  maxTimelineItems: 24,\n  maxBreadcrumbItems: 12,\n  maxKeyValuePairs: 24,\n  /** Maximum `file-tree` nesting. */\n  maxTreeDepth: 6,\n  /** Maximum `blocks` figure rows / cells per row. Cells are data, not nodes,\n   *  so a wide figure still costs one node against `maxNodes`. */\n  maxBlocksRows: 14,\n  maxBlocksCells: 16,\n  /** Maximum `diagram` nodes / edges / zones / focal accents. */\n  maxDiagramNodes: 9,\n  maxDiagramEdges: 12,\n  maxDiagramZones: 3,\n  maxDiagramFocal: 2,\n  maxDiagramLabel: 14,\n  /** Maximum depth of an `echart` option object. */\n  maxEChartOptionDepth: 10,\n  /** Maximum length of any single array inside an `echart` option. */\n  maxEChartArrayLen: 500,\n  /** Maximum entries traversed while sanitizing an `echart` option. */\n  maxEChartOptionNodes: 2000,\n} as const\n"
    },
    {
      "path": "src/client/guard.ts",
      "content": "/**\n * GenUI spec guard: resource limits, structural validation, and deterministic\n * repair for ```dsh-ui fence specs.\n *\n * The renderer path runs every fence body through `repairGenuiSpec` before\n * rendering, so a pathological or hostile spec — deep nesting, thousands of\n * nodes, oversized strings, out-of-range numbers — degrades gracefully instead\n * of stalling the UI. Repair is deterministic and prefix-stable: a component\n * that survives repair of a partial stream keeps its position when later\n * chunks arrive, so streaming re-renders stay consistent.\n *\n * Policy:\n * - Unsupported node types are rejected by validation and dropped by repair.\n * - Known types: required fields must have the right type or the node is\n *   dropped; numbers are clamped into range; strings truncated; arrays\n *   sliced to their caps; containers recursed with a depth budget.\n * - The whole spec carries a node budget; once exhausted, remaining siblings\n *   are elided.\n */\nimport type { GenuiWhen, GenuiComparePanel, GenuiComputed, GenuiComputedFormat, GenuiComputedRef, GenuiFileTreeNode, GenuiList, GenuiNode, GenuiPlot, GenuiPlotSeries, GenuiScene3D, GenuiSpec, GenuiDiagram, GenuiDiagramTheme, GenuiDiagramKind } from './spec.ts'\nimport { isComponentRoot, wrapSingleComponentRoot } from './spec.ts'\nimport {\n  BADGE_TONES, BUTTON_TONES, CALLOUT_TONES, CARD_TONES, CHART_KINDS, CHOICE_MODES, COMPARE_MODES, COMPONENT_SCHEMAS, HERO_TONES, WHEN_OPS,\n  DIAGRAM_EDGE_KINDS, DIAGRAM_KINDS, DIAGRAM_NODE_TYPES, DIAGRAM_ROUTES, DIAGRAM_VARIANTS, POPOVER_PLACEMENTS, POPOVER_TRIGGERS,\n  DATE_PICKER_MODES, ECHART_PRESETS, FILE_TYPES, GENUI_NATIVE_TYPES, GENUI_SPEC_SCHEMA, INPUT_TYPES, getComponentSchema,\n  ARROW_DIRS, BLOCKS_VARIANTS, BLOCK_CELL_TONES, ICON_TONES, MEDIA_ASPECT_RATIOS, MESH_SHAPES, PLOT_KINDS, PROGRESS_VARIANTS, ROW_JUSTIFY, TABLE_CELL_TYPES, TEXT_ALIGNS, TEXT_SIZES, TEXT_TONES,\n} from './genui-runtime/schema.ts'\nimport type { ComponentFieldKind, ComponentRecordSchema, ComponentSchema } from './genui-runtime/schema.ts'\nimport { normalizeGenuiSpec } from './genui-runtime/normalize.ts'\nimport { diagnoseUnknownGenuiFields } from './genui-runtime/diagnostics.ts'\nimport type { GenuiDiagnostic } from './genui-runtime/diagnostics.ts'\nimport { GENUI_LIMITS } from './genui-runtime/limits.ts'\nimport { analyzeSubmissionRegistry } from './submission-registry.ts'\nimport { isTableDetailReachable, prepareTableRows, tableRowsForDetails } from './table-details.ts'\nimport { walkGenuiNodes } from './walk-spec.ts'\nimport { color, enu, int, num, obj, opt, safeMediaSrc, str } from './genui-runtime/value-utils.ts'\nimport { repairMap, validateMap } from './map-data.ts'\nimport { isDatePickerValueValid, isIsoDate } from './date-picker.ts'\nimport { classifyLinkTarget } from './file-link.ts'\nimport { buildComputedGraph, getComputedInputIds, getDuplicateComputedInputIds, getComputedTemplateScope, getComputedChildNodeScope } from './computed.ts'\nimport type { ComputedTemplateScope, ComputedNodeScope } from './computed.ts'\nimport { SAFE_MATH_LIMITS } from './safe-math.ts'\n\n/** Result of `validateGenuiSpec`. */\nexport interface GenuiValidation {\n  ok: boolean\n  /** Human-readable problems, empty when `ok`. */\n  errors: string[]\n}\n\n/* ---------------- schema field helpers ---------------- */\n\nfunction fieldKindMatches(value: unknown, kind: ComponentFieldKind): boolean {\n  switch (kind) {\n    case 'string': return typeof value === 'string'\n    case 'string-or-null': return value === null || typeof value === 'string'\n    case 'number': return typeof value === 'number' && Number.isFinite(value)\n    case 'boolean': return typeof value === 'boolean'\n    case 'nodes': return Array.isArray(value)\n    case 'array': return Array.isArray(value)\n    case 'object': return obj(value) !== undefined\n    case 'unknown': return true\n  }\n}\n\nfunction fieldKindLabel(kind: ComponentFieldKind): string {\n  switch (kind) {\n    case 'string-or-null': return 'a string or null'\n    case 'number': return 'a finite number'\n    case 'boolean': return 'a boolean'\n    case 'nodes': case 'array': return 'an array'\n    case 'object': return 'an object'\n    case 'unknown': return 'a value'\n    default: return 'a string'\n  }\n}\n\n/** Detect an existing field diagnostic using both canonical and legacy messages. */\nfunction hasFieldError(errors: readonly string[], at: string, field: string): boolean {\n  return errors.some(error =>\n    error.startsWith(`${at}.${field} `) || error.includes(`'${field}'`) || error.includes(`requires ${field}`))\n}\n\n/** Validate present fields against the runtime schema without duplicating errors. */\nfunction validateSchemaFieldKinds(\n  value: Record<string, unknown>,\n  at: string,\n  definition: ComponentSchema,\n  errors: string[],\n  excludedFields: readonly string[] = [],\n): void {\n  for (const [field, kind] of Object.entries(definition.fields)) {\n    if (excludedFields.includes(field) || value[field] === undefined) continue\n    if (!fieldKindMatches(value[field], kind) && !hasFieldError(errors, at, field)) {\n      errors.push(`${at}.${field} must be ${fieldKindLabel(kind)}`)\n    }\n  }\n  for (const [field, values] of Object.entries(definition.enums)) {\n    if (excludedFields.includes(field) || value[field] === undefined || !fieldKindMatches(value[field], 'string')) continue\n    if (!values.includes(value[field] as string) && !hasFieldError(errors, at, field)) {\n      errors.push(`${at}.${field} must be one of ${values.join(', ')}`)\n    }\n  }\n}\n\n/** Validate one schema-declared nested record and all records below it. */\nfunction validateRecordSchema(\n  value: unknown,\n  at: string,\n  definition: ComponentRecordSchema,\n  errors: string[],\n): void {\n  const holder = obj(value)\n  if (holder === undefined) {\n    errors.push(`${at} must be an object`)\n    return\n  }\n  for (const field of definition.required) {\n    const kind = definition.fields[field]\n    if (holder[field] === undefined) {\n      if (!hasFieldError(errors, at, field)) errors.push(`${at}: requires ${field}${kind === undefined ? '' : ` (${fieldKindLabel(kind)})`}`)\n    } else if (kind !== undefined && !fieldKindMatches(holder[field], kind)) {\n      if (!hasFieldError(errors, at, field)) errors.push(`${at}.${field} must be ${fieldKindLabel(kind)}`)\n    }\n  }\n  for (const [field, kind] of Object.entries(definition.fields)) {\n    if (holder[field] !== undefined && !fieldKindMatches(holder[field], kind)) {\n      if (!hasFieldError(errors, at, field)) errors.push(`${at}.${field} must be ${fieldKindLabel(kind)}`)\n    }\n  }\n  for (const [field, values] of Object.entries(definition.enums)) {\n    if (holder[field] !== undefined && typeof holder[field] === 'string' && !values.includes(holder[field])) {\n      if (!hasFieldError(errors, at, field)) errors.push(`${at}.${field} must be one of ${values.join(', ')}`)\n    }\n  }\n  for (const [field, nested] of Object.entries(definition.nested)) {\n    const nestedValue = holder[field]\n    if (nestedValue === undefined) continue\n    if (Array.isArray(nestedValue)) {\n      nestedValue.forEach((item, index) => validateRecordSchema(item, `${at}.${field}[${index}]`, nested, errors))\n    } else {\n      validateRecordSchema(nestedValue, `${at}.${field}`, nested, errors)\n    }\n  }\n}\n\n/** Validate registry-declared nested records before repair can discard them. */\nfunction validateNestedRecordSchemas(\n  value: Record<string, unknown>,\n  at: string,\n  definition: ComponentSchema,\n  errors: string[],\n): void {\n  for (const [field, nested] of Object.entries(definition.nested)) {\n    const nestedValue = value[field]\n    if (nestedValue === undefined) continue\n    if (Array.isArray(nestedValue)) {\n      const records = value.type === 'image-group' && field === 'items'\n        ? nestedValue.slice(0, GENUI_LIMITS.maxImageGroupItems)\n        : value.type === 'entity-card' && field === 'metadata' ? nestedValue.slice(0, GENUI_LIMITS.maxEntityMetadata)\n        : value.type === 'entity-card' && field === 'actions' ? nestedValue.slice(0, GENUI_LIMITS.maxEntityActions)\n        : value.type === 'map' && field === 'locations' ? nestedValue.slice(0, GENUI_LIMITS.maxMapLocations)\n        : value.type === 'map' && field === 'routes' ? nestedValue.slice(0, GENUI_LIMITS.maxMapRoutes)\n        : field === 'computed' ? nestedValue.slice(0, GENUI_LIMITS.maxComputedFields) : nestedValue\n      records.forEach((item, index) => validateRecordSchema(item, `${at}.${field}[${index}]`, nested, errors))\n    } else {\n      validateRecordSchema(nestedValue, `${at}.${field}`, nested, errors)\n    }\n  }\n}\n\n/**\n * Does this table state its columns implicitly, in a 2D `rows`/`data` body?\n * Repair turns the leading row into the header (see `deriveTableColumns`), so\n * validation must not report the missing `columns` that repair is about to\n * supply — while still reporting it for bodies repair cannot read (a scalar\n * `rows`, an empty array, a 1D list).\n */\nfunction hasDerivableTableColumns(value: Record<string, unknown>): boolean {\n  const rows = value.rows !== undefined ? value.rows : value.data\n  if (!Array.isArray(rows) || rows.length === 0) return false\n  return Array.isArray(rows[0])\n}\n\n/** Validate the registry-declared presence and primitive shape of a native node. */\nfunction validateRegistryFields(\n  value: Record<string, unknown>,\n  at: string,\n  definition: ComponentSchema,\n  errors: string[],\n): void {\n  const type = String(value.type)\n  const alreadyReported = (field: string): boolean => hasFieldError(errors, at, field)\n  const derivableField = type === 'table' && hasDerivableTableColumns(value) ? 'columns' : null\n  for (const field of definition.required) {\n    const kind = definition.fields[field]\n    if (kind === undefined || value[field] === undefined) {\n      if (field !== derivableField && !alreadyReported(field)) errors.push(`${at}: type '${type}' requires ${field}${kind === undefined ? '' : ` (${fieldKindLabel(kind)})`}`)\n      continue\n    }\n    if (!fieldKindMatches(value[field], kind) && !alreadyReported(field)) errors.push(`${at}.${field} must be ${fieldKindLabel(kind)}`)\n  }\n  validateSchemaFieldKinds(value, at, definition, errors, ['type'])\n  for (const group of definition.oneOfRequired) {\n    if (!group.some(field => value[field] !== undefined)\n      && !errors.some(error => error.includes(`requires ${group.join(' or ')}`))) {\n      errors.push(`${at}: type '${type}' requires one of ${group.join(' or ')}`)\n    }\n  }\n  for (const rule of definition.conditionalRequired) {\n    if (value[rule.when.field] !== rule.when.equals) continue\n    for (const field of rule.required) {\n      if (value[field] === undefined && !alreadyReported(field)) {\n        errors.push(`${at}: type '${type}' requires ${field}${rule.message === undefined ? '' : ` (${rule.message})`}`)\n      }\n    }\n  }\n  validateNestedRecordSchemas(value, at, definition, errors)\n}\n\n/* ---------------- repair ---------------- */\n\ninterface RepairCtx {\n  /** Nodes left in the budget; 0 stops the walk. */\n  remaining: number\n  /** Rows, list entries, and tree nodes omitted by their per-component caps. */\n  truncatedTableRows: number\n  truncatedListItems: number\n  truncatedFileTreeItems: number\n}\n\n/** Walk `list` with the shared node budget; drops invalid entries. */\nfunction repairItems(list: unknown, ctx: RepairCtx, depth: number): GenuiNode[] {\n  if (!Array.isArray(list)) return []\n  const out: GenuiNode[] = []\n  for (const item of list) {\n    if (ctx.remaining <= 0) break\n    ctx.remaining -= 1\n    const node = repairNode(item, ctx, depth)\n    if (node !== null) out.push(node)\n  }\n  return out\n}\n\n/** Optional explicit palette: up to 12 validated colour values. */\nfunction paletteValues(v: unknown): string[] | undefined {\n  if (!Array.isArray(v)) return undefined\n  const out: string[] = []\n  for (const item of v.slice(0, 12)) {\n    const value = color(item)\n    if (value === undefined) continue\n    out.push(value)\n  }\n  return out.length > 0 ? out : undefined\n}\n\n/** Optional `stat.spark` series: finite numbers only, 2..60 points. */\nfunction sparkValues(v: unknown): number[] | undefined {\n  if (!Array.isArray(v)) return undefined\n  const out: number[] = []\n  for (const item of v.slice(0, 60)) {\n    const n = typeof item === 'number' ? item : Number(item)\n    if (!Number.isFinite(n)) return undefined\n    out.push(n)\n  }\n  return out.length >= 2 ? out : undefined\n}\n\n/** Layout hints are component-agnostic: `span` and `when` survive repair on ANY\n *  node (the renderer applies them inside a layout / before paint). Kept out of\n *  the per-case switches so a new component type cannot forget them. */\nfunction repairNode(value: unknown, ctx: RepairCtx, depth: number): GenuiNode | null {\n  const node = repairNodeFields(value, ctx, depth)\n  if (node === null) return null\n  const raw = obj(value)\n  const span = int(raw?.span, 2, 12)\n  const when = repairWhen(raw?.when)\n  const enableWhen = repairWhen(raw?.enableWhen)\n  const disabledReason = str(raw?.disabledReason, 200)\n  const extras = {\n    ...(span === undefined ? {} : { span }),\n    ...(when === undefined ? {} : { when }),\n    ...(enableWhen === undefined ? {} : { enableWhen }),\n    ...(disabledReason === undefined ? {} : { disabledReason }),\n  }\n  return Object.keys(extras).length === 0 ? node : ({ ...node, ...extras } as GenuiNode)\n}\n\n/** Repair a `when` clause; a malformed one is dropped (node stays visible). */\nfunction repairWhen(value: unknown): GenuiWhen | undefined {\n  const v = obj(value)\n  if (v === undefined) return undefined\n  const field = str(v.field, 80)\n  const op = enu(v.op, WHEN_OPS)\n  if (field === undefined || op === undefined) return undefined\n  const raw = v.value\n  const value_ = Array.isArray(raw)\n    ? (raw.length > 0 && raw.length <= 12\n      ? raw.filter(entry => typeof entry === 'string' || typeof entry === 'number')\n        .map(entry => (typeof entry === 'number' ? entry : str(entry, 120) ?? ''))\n        .filter(entry => entry !== '')\n      : undefined)\n    : (typeof raw === 'string' || typeof raw === 'number' || typeof raw === 'boolean' ? raw : undefined)\n  const value2 = Array.isArray(value_) && value_.length === 0 ? undefined : value_\n  return { field, op, ...(value2 === undefined ? {} : { value: value2 }) }\n}\n\nfunction repairNodeFields(value: unknown, ctx: RepairCtx, depth: number): GenuiNode | null {\n  if (depth > GENUI_LIMITS.maxDepth) return null\n  const v = obj(value)\n  if (v === undefined) return null\n  const type = v.type\n  if (typeof type !== 'string') return null\n  switch (type) {\n    case 'text': {\n      const content = str(v.content, GENUI_LIMITS.maxString) ?? str(v.text, GENUI_LIMITS.maxString)\n      if (content === undefined) return null\n      // `center: true` is the legacy shorthand; a display-level size is the\n      // one-per-answer focal tier (B1), so it rides the same enum gate.\n      return {\n        type: 'text', content,\n        ...opt('size', enu(v.size, TEXT_SIZES)),\n        ...opt('align', enu(v.align, TEXT_ALIGNS)),\n        ...opt('tone', enu(v.tone, TEXT_TONES)),\n        ...opt('mono', v.mono === true ? true : undefined),\n        ...opt('center', v.center === true ? true : undefined),\n      }\n    }\n    case 'icon': {\n      // `name` 是原型链攻击面（渲染器用 Object.hasOwn 兜住），但长度仍要截断；\n      // `size` 走 clamp。未知名字不在这里判死——渲染层降级成圆点。\n      const name = str(v.name, 64)\n      if (name === undefined) return null\n      return {\n        type: 'icon', name,\n        ...opt('label', str(v.label, GENUI_LIMITS.maxString)),\n        ...opt('tone', enu(v.tone, ICON_TONES)),\n        ...opt('size', int(v.size, 8, 96)),\n        ...opt('tile', v.tile === true ? true : undefined),\n      }\n    }\n    case 'blocks': {\n      // rows/cells 是数据不是节点，此前走 default 透传，于是颜色绕过了\n      // color()/SAFE_COLOR_RE、字符串绕过了 maxString。这里补齐：\n      // 颜色只接受字面色或宿主令牌，字符串按 maxString 截断，行/格按 limits 截断。\n      if (!Array.isArray(v.rows)) return null\n      const rows = v.rows.slice(0, GENUI_LIMITS.maxBlocksRows).flatMap((entry) => {\n        const row = obj(entry)\n        if (row === undefined || !Array.isArray(row.cells)) return []\n        const cells = row.cells.slice(0, GENUI_LIMITS.maxBlocksCells).map((cell) => {\n          if (cell === null) return null\n          if (typeof cell === 'string') return str(cell, GENUI_LIMITS.maxString) ?? ''\n          const holder = obj(cell)\n          if (holder === undefined) return null\n          const text = str(holder.text, GENUI_LIMITS.maxString)\n          if (text === undefined) return null\n          return {\n            text,\n            ...opt('color', color(holder.color)),\n            ...opt('tone', enu(holder.tone, BLOCK_CELL_TONES)),\n            ...opt('sub', str(holder.sub, 128)),\n          }\n        })\n        return [{\n          cells,\n          ...opt('label', str(row.label, 128)),\n          ...opt('color', color(row.color)),\n          ...opt('variant', enu(row.variant, BLOCKS_VARIANTS)),\n        }]\n      })\n      if (rows.length === 0) return null\n      return {\n        type: 'blocks', rows,\n        ...opt('columns', int(v.columns, 1, GENUI_LIMITS.maxBlocksCells)),\n        ...opt('title', str(v.title, GENUI_LIMITS.maxString)),\n        ...opt('caption', str(v.caption, GENUI_LIMITS.maxString)),\n      }\n    }\n    case 'arrow': {\n      return {\n        type: 'arrow',\n        ...opt('dir', enu(v.dir, ARROW_DIRS)),\n        ...opt('length', int(v.length, 16, 96)),\n        ...opt('label', str(v.label, 200)),\n      }\n    }\n    case 'row': {\n      return {\n        type: 'row',\n        items: repairItems(v.items, ctx, depth + 1),\n        ...opt('wrap', v.wrap === true ? true : undefined),\n        ...opt('spacer', v.spacer === true ? true : undefined),\n        // Repair rebuilds every node from a hand-written field list, so a\n        // schema-only addition is silently dropped here. Keep the two in sync:\n        // figure headers need `justify: \"center\"` (icon + title over a caption).\n        ...opt('justify', enu(v.justify, ROW_JUSTIFY)),\n      }\n    }\n    case 'carousel': {\n      const source = Array.isArray(v.items) ? v.items.slice(0, GENUI_LIMITS.maxCarouselItems) : []\n      return {\n        type: 'carousel', items: repairItems(source, ctx, depth + 1),\n        ...opt('title', str(v.title, GENUI_LIMITS.maxString)),\n        ...opt('itemWidth', num(v.itemWidth, 80, 640)),\n        ...opt('gap', num(v.gap, 0, Number.MAX_SAFE_INTEGER / 4)),\n      }\n    }\n    case 'image-group': {\n      const source = Array.isArray(v.items) ? v.items.slice(0, GENUI_LIMITS.maxImageGroupItems) : []\n      const items = source.flatMap(value => {\n        const item = obj(value)\n        const src = safeMediaSrc(item?.src)\n        if (item === undefined || src === undefined) return []\n        return [{ src, ...opt('alt', str(item.alt, GENUI_LIMITS.maxString)), ...opt('caption', str(item.caption, GENUI_LIMITS.maxString)) }]\n      })\n      return { type: 'image-group', items, ...opt('title', str(v.title, GENUI_LIMITS.maxString)) }\n    }\n    case 'editor': {\n      const id = str(v.id, 200)\n      const value = str(v.value, GENUI_LIMITS.maxEditorChars)\n      if (id === undefined || value === undefined) return null\n      return {\n        type: 'editor', id, value,\n        ...opt('label', str(v.label, GENUI_LIMITS.maxString)),\n        ...opt('placeholder', str(v.placeholder, GENUI_LIMITS.maxString)),\n        ...opt('rows', int(v.rows, 3, 24)),\n      }\n    }\n    case 'entity-card': {\n      const name = str(v.name, GENUI_LIMITS.maxString)\n      if (name === undefined) return null\n      const metadata = Array.isArray(v.metadata) ? v.metadata.slice(0, GENUI_LIMITS.maxEntityMetadata).flatMap(entry => {\n        const record = obj(entry)\n        const label = str(record?.label, 120)\n        const value = str(record?.value, GENUI_LIMITS.maxString)\n        return label === undefined || value === undefined ? [] : [{ label, value }]\n      }) : undefined\n      const actions = Array.isArray(v.actions) ? v.actions.slice(0, GENUI_LIMITS.maxEntityActions).flatMap(entry => {\n        const record = obj(entry)\n        const label = str(record?.label, 120)\n        const action = str(record?.action, 200)\n        if (label === undefined || action === undefined) return []\n        return [{ label, action, ...opt('tone', enu(record?.tone, BUTTON_TONES)) }]\n      }) : undefined\n      const image = safeMediaSrc(v.image)\n      const hrefTarget = classifyLinkTarget(v.href)\n      const href = hrefTarget.type === 'external' ? hrefTarget.href : hrefTarget.type === 'file' ? String(v.href).trim() : undefined\n      return {\n        type: 'entity-card', name,\n        ...opt('image', image),\n        ...opt('imageAlt', str(v.imageAlt, GENUI_LIMITS.maxString)),\n        ...opt('description', str(v.description, GENUI_LIMITS.maxString)),\n        ...opt('metadata', metadata),\n        ...opt('href', href),\n        ...opt('sourceLabel', str(v.sourceLabel, 120)),\n        ...opt('actions', actions),\n      }\n    }\n    case 'popover': {\n      const label = str(v.label, 200)\n      const content = str(v.content, GENUI_LIMITS.maxString)\n      if (label === undefined || content === undefined) return null\n      return {\n        type: 'popover', label, content,\n        ...opt('trigger', enu(v.trigger, POPOVER_TRIGGERS)),\n        ...opt('placement', enu(v.placement, POPOVER_PLACEMENTS)),\n      }\n    }\n    case 'choices': {\n      const source = Array.isArray(v.items) ? v.items.slice(0, 8) : []\n      const items = source.flatMap(value => {\n        const item = obj(value)\n        const label = str(item?.label, 120)\n        if (item === undefined || label === undefined) return []\n        const disabled = item.disabled === true\n        return [{\n          label,\n          ...opt('hint', str(item.hint, 200)),\n          ...opt('meta', str(item.meta, 40)),\n          ...(item.recommended === true ? { recommended: true } : {}),\n          ...(disabled ? { disabled: true } : {}),\n          // A disabled option without a reason is a dead end; keep whatever the\n          // model wrote so the reader can see WHY.\n          ...opt('reason', str(item.reason, 200)),\n        }]\n      })\n      if (items.length === 0) return null\n      return {\n        type: 'choices', items,\n        ...opt('title', str(v.title, GENUI_LIMITS.maxString)),\n        ...opt('prompt', str(v.prompt, 400)),\n        ...opt('mode', enu(v.mode, CHOICE_MODES)),\n        ...opt('submit', str(v.submit, 60)),\n        ...opt('action', str(v.action, 200)),\n        ...opt('max', int(v.max, 1, items.length)),\n        ...opt('group', str(v.group, 60)),\n        ...opt('explanation', str(v.explanation, GENUI_LIMITS.maxString)),\n        // `answer` is an index OR a label; both are legal, so only the shape is\n        // checked here and the grader resolves it against the item list.\n        ...(typeof v.answer === 'number' || typeof v.answer === 'string' ? { answer: v.answer } : {}),\n      }\n    }\n    case 'compare': {\n      // A pair with one usable side is not a comparison: drop the node rather\n      // than ship a lone image under a two-sided caption.\n      const panel = (value: unknown): GenuiComparePanel | undefined => {\n        const item = obj(value)\n        const src = safeMediaSrc(item?.src)\n        if (item === undefined || src === undefined) return undefined\n        return {\n          src,\n          ...opt('label', str(item.label, 40)),\n          ...opt('alt', str(item.alt, GENUI_LIMITS.maxString)),\n          ...opt('caption', str(item.caption, GENUI_LIMITS.maxString)),\n        }\n      }\n      const before = panel(v.before)\n      const after = panel(v.after)\n      if (before === undefined || after === undefined) return null\n      return {\n        type: 'compare', before, after,\n        ...opt('title', str(v.title, GENUI_LIMITS.maxString)),\n        ...opt('mode', enu(v.mode, COMPARE_MODES)),\n        ...opt('height', int(v.height, 120, 640)),\n      }\n    }\n    case 'col': {\n      return {\n        type: 'col',\n        items: repairItems(v.items, ctx, depth + 1),\n        ...opt('gap', num(v.gap, 0, 96)),\n        ...opt('width', num(v.width, 1, 100)),\n      }\n    }\n    case 'grid': {\n      return { type: 'grid', cols: int(v.cols, 1, GENUI_LIMITS.maxGridCols) ?? 1, items: repairItems(v.items, ctx, depth + 1) }\n    }\n    case 'card': {\n      return {\n        type: 'card',\n        items: repairItems(v.items, ctx, depth + 1),\n        ...opt('eyebrow', str(v.eyebrow, 64)),\n        ...opt('title', str(v.title, GENUI_LIMITS.maxString)),\n        ...opt('tone', enu(v.tone, CARD_TONES)),\n        ...opt('accent', color(v.accent)),\n        ...opt('flat', v.flat === true ? true : undefined),\n      }\n    }\n    case 'button': {\n      const label = str(v.label, GENUI_LIMITS.maxString)\n      if (label === undefined) return null\n      return {\n        type: 'button', label,\n        ...opt('tone', enu(v.tone, BUTTON_TONES)),\n        ...opt('full', v.full === true ? true : undefined),\n        ...opt('small', v.small === true ? true : undefined),\n        ...opt('icon', str(v.icon, 64)),\n        ...opt('action', str(v.action, 200)),\n      }\n    }\n    case 'input': {\n      return {\n        type: 'input',\n        ...opt('label', str(v.label, GENUI_LIMITS.maxString)),\n        ...opt('placeholder', str(v.placeholder, GENUI_LIMITS.maxString)),\n        ...opt('value', str(v.value, GENUI_LIMITS.maxString)),\n        ...opt('inputType', enu(v.inputType, INPUT_TYPES)),\n        ...opt('action', str(v.action, 200)),\n        ...opt('id', str(v.id, 200)),\n      